// Bundle the installed, pinned Leaflet runtime for an offline WebView shell.
// Only OSM tiles are fetched remotely. Run again after updating Leaflet.
const fs = require('node:fs');
const path = require('node:path');
const root = path.dirname(require.resolve('leaflet/package.json'));
fs.mkdirSync('src/map', {recursive: true});
const js = fs.readFileSync(path.join(root, 'dist/leaflet.js'), 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '');
const css = fs.readFileSync(path.join(root, 'dist/leaflet.css'), 'utf8');
fs.writeFileSync('src/map/leafletAssets.ts', '// Generated by scripts/bundle-leaflet.cjs; Leaflet 1.9.4, BSD-2-Clause.\nexport const leafletJS = ' + JSON.stringify(js) + ';\nexport const leafletCSS = ' + JSON.stringify(css) + ';\n');
fs.copyFileSync(path.join(root, 'LICENSE'), 'src/map/LEAFLET-LICENSE');
